import{_ as t,a as o,b as a,c as n,d as i,e as r,f as s,g as l}from"./chunks/a37af272e9c4c5b4cf1d.CvIkSzP-.js";import{_ as p,o as h,c as u,a5 as d}from"./chunks/framework.DNkHA0lr.js";const I=JSON.parse('{"title":"How To Escape Beginner Hell As A Creator","description":"","frontmatter":{"title":"How To Escape Beginner Hell As A Creator","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/how-to-escape-beginner-hell-as-a-creator.md","filePath":"en/letters/how-to-escape-beginner-hell-as-a-creator.md"}'),c={name:"en/letters/how-to-escape-beginner-hell-as-a-creator.md"};function m(y,e,g,w,f,b){return h(),u("div",null,[...e[0]||(e[0]=[d('<h1 id="how-to-escape-beginner-hell-as-a-creator" tabindex="-1">How To Escape Beginner Hell As A Creator <a class="header-anchor" href="#how-to-escape-beginner-hell-as-a-creator" aria-label="Permalink to &quot;How To Escape Beginner Hell As A Creator&quot;">​</a></h1><p>Dan Koe · 2025-01-25 · <a href="https://thedankoe.com/letters/how-to-escape-beginner-hell-as-a-creator/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/how-to-escape-beginner-hell-as-a-creator">返回中文译文</a></p><p><a href="https://www.youtube.com/embed/REwaFvbelEk?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>3-6 months.</p><p>That’s how long most creators are trapped in beginner hell.</p><p>You know, that dreadful place where you feel like you don’t know what you’re doing. You question whether it’s worth it to keep going. You’re thinking of what you’re going to try next (just to do it all over again). Unfortunately, most people quit before things start to get good.</p><p>But understand this:</p><p>Most people think the answer is to “just be consistent.”</p><p>To keep pushing through even when you aren’t making progress.</p><p>Zero likes. Zero followers. Zero sales. It’s one of the most painful things in the world. Becoming a creator was supposed to be your ticket to the good life, wasn’t it? Or was it all just a scam? A pipe dream sold to you by marketers and gurus?</p><p>Here’s the brutal truth… <em>you aren’t making progress because you aren’t doing the right things.</em></p><p>So before you go back to the life of comfort you swore to leave behind, listen to what I have to say.</p><p>You need to reach the point where everything “clicks.” You need that “aha!” moment where clarity strikes and you know exactly how to break through to intermediate heaven.</p><p>I know you’re on the edge right now.</p><p>But remember why you started.</p><p>You know you want to do something creative.</p><p>You know you need an audience to do that outside of a job.</p><p>You know you want to be in control of the money you make and the lifestyle you design.</p><p>You know that, in order to do those things, you need to write or create. You need to become your own media company that attracts people to your independent work. Your self-published books. Your music. Your ideas. Your expertise.</p><p>You just need to reach that glorious moment—the “click”—and you will finally feel in control of your future.</p><p>Let me help.</p><h2 id="how-to-escape-beginner-hell" tabindex="-1">How To Escape Beginner Hell <a class="header-anchor" href="#how-to-escape-beginner-hell" aria-label="Permalink to &quot;How To Escape Beginner Hell&quot;">​</a></h2><blockquote><p>All overnight success takes about 10 years. – Jeff Bezos</p></blockquote><p>Now, there is a series of actions you can take that will lead to results.</p><p>Plain and simple.</p><p>But most creators mindlessly follow the instructions they were given in a video, course, or article.</p><p>My friend, this isn’t a job with a linear set of steps you can perform everyday, shut your mind off, and live like you always have. This is a one-person business. You are the CEO. You are the CMO. You are the COO. You are everything. Please start acting like it. Get it together.</p><p>I know because I was in beginner hell for almost 5 years.</p><p>I jumped between dropshipping, 3 ecommerce stores, digital art and photography, a Facebook ads agency, an SEO content agency, and eventually had to get a job in web design because the loans were piling up and I wasn’t willing to drown any longer.</p><p>At my job, I procrastinated all my work to make freelance web design work. When I started writing on social media to land more clients, I didn’t experience a beginner hell because I knew how to avoid it.</p><p>The skills I learned along the way led to my own “click.” I’ll tell you what those are, but they involve:</p><ul><li>A different way to think about finding your niche</li><li>The best type of content to bring in followers</li><li>How to monetize without relying on platform ad revenue</li><li>Why you should forget building a funnel because social media has changed</li></ul><p>And much more that I’ll leave to your imagination. I am going to give you a condensed social media masterclass so you can finally feel like you have control over your life’s work. I am going to tell you how to end up like this guy:</p><p><img src="'+t+'" alt=""></p><p>After teaching writing and content to almost 30,000 students, here are the 7 tips, strategies, and insights that will change everything for you:</p><h3 id="_1-do-what-works-for-beginners" tabindex="-1">1) Do What Works For Beginners <a class="header-anchor" href="#_1-do-what-works-for-beginners" aria-label="Permalink to &quot;1) Do What Works For Beginners&quot;">​</a></h3><p>Beginner hell can last anywhere from 3 months to 30 years.</p><p>For some people, it lasts their entire life (starving artists).</p><p>Why?</p><p>Because beginners don’t realize what advanced creators do now <em>is not</em> what they did to grow in the first place.</p><p>And that’s the most important point of this letter:</p><p><em>You aren’t growing because you aren’t doing the things that lead to growth.</em></p><p>Beginners start posting philosophical quotes or try to be the next Marcus Aurelius when nobody knows who they are or cares about what they do. They have no <em>authority.</em></p><p>I hate to break it to you, but you aren’t a Roman Emperor.</p><p>You aren’t respected because nobody knows who you are.</p><p>That means you have to build authority <em>on</em> social media before people care about your cute little fortune cookie posts.</p><p>How do you build authority?</p><p><strong>1 – Solve more problems.</strong></p><p>80% of your content as a beginner should start with a pain point.</p><p>If you are just writing ideas without any second thought, you aren’t going to go very far. You need to be meticulous with the structure of your posts at the start.</p><p>With every idea you want to write about, think about a pain point that the average person faces. Start with that in your content.</p><p>Use phrases like:</p><ul><li><strong>“Most people”</strong> – i.e. Most people suck at writing.</li><li><strong>“If you struggle with”</strong> – i.e. If you struggle to focus for more than 5 minutes.</li><li><strong>“The worst”</strong> – i.e. The worst skill you can learn is web design.</li></ul><p>I use these quite often in my content because <em>they work.</em></p><p>Problems capture attention. Problems open a curiosity loop. Problems make it 100x easier to make the rest of the post impactful.</p><p>Start with the problem, then finish it with a list of steps, your unique perspective, or a novel insight.</p><p><strong>2 – Cover the most important ideas in extreme depth.</strong></p><p>Once you pick a topic, you don’t just start writing random ideas.</p><p>There are a select few evergreen ideas that <em>always</em> perform well within that topic. It’s up to you to find them and write everything you can about them under <em>your own brand.</em></p><p>In something like building a business, those ideas are:</p><ul><li>How to choose a niche</li><li>The best business model for beginners</li><li>The best skills to learn</li><li>How to make X amount of money in Y amount of time</li></ul><p>There’s a reason you see these topics being talked about <em>all the time.</em></p><p>Because they WORK. They work because 95% of the market are beginners. They work because nobody can get sick of the fundamentals.</p><p>Stop trying to avoid writing about the things that people want to learn about.</p><p>“But Dan, everyones talked about these things before, why would they care about me when I do?”</p><p>I need you to zoom out a bit. You’re in beginner hell so it’s easy for your mind to fall into survival mode and not be able to think straight.</p><p>How many times have <em>you</em> read about those topics from different people? Do <em>you</em> care?</p><p>No. Because people need to be reminded more than they need something new.</p><p>Once you know what topic you want to write about, research 5-10 accounts that talk about that thing. Notice what content they repeat on a weekly or monthly basis. Notice what content they all talk about.</p><p>Then, make it a consistent part of your brand.</p><p>Create multiple free guides around those topics.</p><p>Create content about one of them at least once a day.</p><p>Write short, medium, and long form content. Posts, threads, carousels, newsletters, and the rest.</p><p>You need to create a <em>world of content</em> so people can dig as deep as they want into your brand, but that’s something we’ll talk about in a later point.</p><p><strong>3 – Filter your favorite accounts to find their oldest content.</strong></p><p>Chances are, you are copying feel-good ideas from big accounts.</p><p>They already have an audience. They already have a high baseline level of engagement. You have no idea if those posts will work for someone with no authority or skin in the game.</p><p>James Clear can write anything and get thousands of likes. You can’t. Why? Because James has an absurd amount of time in the game and has published a serious amount of value. All people need to do is read his book and they’re a fan. You haven’t written a book, nor do you have the 1 million subscriber email list from blogging that made his book a success in the first place.</p><p>Study what content people created in order to grow. Look at their oldest posts and keep scrolling until you find some posts that did better than others.</p><p>Most people went through their own beginner hell, then they had 1-2 moments where they gained a bunch of followers at once. Find those.</p><h3 id="_2-your-content-isn-t-that-good" tabindex="-1">2) Your Content Isn’t That Good <a class="header-anchor" href="#_2-your-content-isn-t-that-good" aria-label="Permalink to &quot;2) Your Content Isn’t That Good&quot;">​</a></h3><p>Frankly, if you aren’t growing, your content just isn’t that good.</p><p>You can’t just pick a topic and start writing.</p><p>You need to take the reader’s psychology into account.</p><p>You need to become a dopamine dealer.</p><p>You need to <em>capture attention, hold attention, and deliver value.</em></p><p>Most people think they are doing this, but they aren’t. They write a post and send it without any second thought or questioning whether it’s actually good.</p><p>All of those require a lifetime of study within themselves. Hell, even I need to refresh myself on how to do them every month or so.</p><p>I’ve written a previous letter on the <a href="/letters/the-most-important-skill-of-the-21st-century-only-1-use-it">10 Koemmandments of Engagement</a>, so read that if you want to go deeper with examples, but I’ll list them here so you can practice.</p><p>I would highlight recommend writing these down. You can download the <a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex</a> desktop app, open floating capture with <strong>Option+C</strong>, and take notes as you read.</p><p><strong>1) Specific Numbers</strong></p><p>Use specific numbers in your hooks or headlines like “Apples new $1175 iPhone has this new feature.”</p><p>Example:</p><p><img src="'+o+'" alt=""></p><p>This works because it acts as a pattern interrupt (the added authority helps too).</p><p><strong>2) Pattern Interrupts</strong></p><p>A pattern interrupt is something that breaks people out of their normal conditioned patterns.</p><p>On social media, people are scrolling through mostly boring text and images. You need to do something different that makes them stop their scroll.</p><p><strong>3) Negativity Bias</strong></p><p>The human brain is wired to remember and pay attention to negativity.</p><p>This doesn’t mean you need to be negative, it means you should position some of your writing in a negative light (it can still be positive).</p><p>“You are going to achieve great things.”</p><p>Compared to:</p><p>“You will never hit rock bottom again.”</p><p>The second is a lot more potent.</p><p><strong>4) Target Callout</strong></p><p>This is simple, call out the specific person you are talking to.</p><ul><li>If you are in your 20’s…</li><li>Calling all creators, coaches, and freelancers!</li><li>Fathers are a gift to humankind…</li></ul><p>Even if your audience doesn’t fall into the specific group you are calling out, it will allow them to “pick a side” and compare themselves to what you are saying.</p><p><strong>5) Problem Callout</strong></p><p>We talked about this one, but as a crucial reminder:</p><p>Start with the pain point.</p><p><strong>6) Potential Benefit</strong></p><p>One of the most important questions you can answer for your readers is “What’s in it for me?”</p><p>If you ask yourself that question after reading over your content, most people will find that their content lacks any tangible value. You have a cool idea, but people don’t care about it.</p><p>Rewire your mind to think in problems and benefits.</p><p>Start with the problem, imply a desirable transformation with a benefit.</p><p><strong>7) Social Proof</strong></p><p>When you flex your results, experience, or credentials, people assume that you know something they don’t, and they want to continue reading or following.</p><p>Justin Welsh is great at doing this without being cocky:</p><p><img src="'+a+'" alt=""></p><p>Talk about your results.</p><p>AI can’t compete with your results.</p><p>Whether you’re a writer who finished a chapter of their book or a health nut that lost 20 pounds, share your experience. I’m sharing business screenshots because that’s what I have sitting around, but there are plenty of examples in the productivity, health, relationships, or self-improvement in general space. Numbers aren’t only money.</p><p><strong>8) Confidence &amp; Conviction</strong></p><p>This is my favorite point because many people refuse to have conviction in their beliefs. This makes it quite easy to stand out if you can reconcile the phrase “firm beliefs held loosely” in your mind.</p><ul><li>Eliminate words that imply uncertainty</li><li>Speak in absolutes when possible</li><li>Exaggerate your point to add energy</li></ul><p>Of course, do not abuse these for the sake of engagement.</p><p>Rather than saying:</p><p><em>“It may be wise if some people developed their skillset.”</em></p><p>Say:</p><p><em>“It is crucial that everyone on planet earth develops their skill set.”</em></p><p>Here’s a good example:</p><p><img src="'+n+'" alt=""></p><p>I wrote this post almost 5 years ago now.</p><p>That was the first post that brought me almost 600 followers as a beginner.</p><p>Because of that, I kept talking about it, turned it into a thread, then a YouTube video (after 2 years, I focused on one platform at the start), and it is my most viewed video on my channel.</p><p>We will talk about how to make noise and double down on signal in a later point.</p><p><strong>9) Punch, Rhythm, &amp; Readability</strong></p><p>Start short and to the point.</p><p>Then, just like this, continue on with your idea.</p><ul><li>Use line breaks</li><li>People love bullet points</li><li>You can get as creative as you’d like</li></ul><p>Do you notice how I am guiding you down the page?</p><p>How I start short, keep you engaged, and deliver a hint of value?</p><p>Even the bullet list is ordered from the shortest point to longest.</p><p><strong>10) Warnings &amp; Caution</strong></p><p>Read this post:</p><p><img src="'+i+'" alt=""></p><p>I start with warning people about a trap. Then I tell them why.</p><p>This is an incredible way to write engaging content because <em>every topic</em> has a large list of traps that people can fall into. If you can identify what those traps are, you have a list of great content to write.</p><p>You don’t need to use all 10 Koemmandments at once, but I would urge you to have this list open while writing. Before you hit send, ensure that you have at least 2 for short form content and even more for long form content.</p><p>By the way, I talk about all of this in <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer.</a></p><h3 id="_3-start-with-training-wheels" tabindex="-1">3) Start With Training Wheels <a class="header-anchor" href="#_3-start-with-training-wheels" aria-label="Permalink to &quot;3) Start With Training Wheels&quot;">​</a></h3><p>Most people don’t have an idea problem, they have a structure problem.</p><p>Because here’s the thing:</p><p>Any idea can go viral if <em>and only if</em> you structure it the right way.</p><p>Generating ideas isn’t hard. You just passed by at least 50 in this newsletter so far that you could take and run with.</p><p>The problem is, you don’t know how to structure them.</p><p>You haven’t <em>trained your mind to masterfully articulate ideas in an impactful way.</em></p><p>Once you do that, you can turn even the worst idea into something that people can’t stop reading, watching, or listening to.</p><p>Like any other skill, you need to start with training wheels. Here’s what you do:</p><p><strong>1) Create a swipe file.</strong></p><p>If you want to be a creator, you need to keep your finger on the pulse of the market.</p><p>You need to scroll social media not as a consumer, but as a researcher.</p><p>Whenever you see a viral idea that makes you think, “Damn, I wish I wrote that.” Save it. Copy the link into Kortex capture and organize it into a “Swipe File” document by typing “@.”</p><p>Think of your brand as an amalgamation of the ideas you love, the ideas that impacted you most, and the ideas you want to be included under your brand.</p><p>Now, you can use those ideas as inspiration, but that’s not the full point.</p><p>You are saving these content pieces so you can emulate the structure.</p><p>Let’s take this post from before as an example:</p><p><img src="'+r+'" alt=""></p><p>You can see a clear <em>structure:</em></p><ul><li>Broad hook with a desired outcome and specific number</li><li>5 exaggerated and polarizing steps in a bullet list</li><li>Additional context that answers the objection “well I can’t disappear completely! I have friends and family!!”</li><li>Last line that ties everything together</li></ul><p>So, if I were to plug in a different idea that I got from a random book like, “meditation is running for the mind” I could turn it into something completely new:</p><p><em>How to clear your mind in 60 seconds:</em></p><ul><li><em>Lock yourself in a room</em></li><li><em>Sit in the corner</em></li><li><em>Breath deep into your belly</em></li><li><em>FEEL the breath with all senses</em></li><li><em>Repeat for one minute</em></li></ul><p><em>Any time you get distracted, refocus your attention on the breath.</em></p><p><em>“Meditation sprints” are how you achieve calm, fast.</em></p><p>If you want to get more creative with it, use the 10 Koemmandments above to change out the hook and let that shape the post more.</p><p>Instead of “How to clear your mind in 60 seconds,” I could focus on a pain point, statistic, target call out, or spin it in a negative lens like “How to destroy negative thoughts in 60 seconds.”</p><p>Yes, this requires you to think and sit with the idea.</p><p>The goal here is to practice this so much that it becomes second nature. You start writing texts to your mom in a persuasive way. You start speaking in a way people want to listen to. The benefits of this go far beyond gaining a few followers.</p><p>Last, don’t just do this with tweets. You can study long videos, short videos, or anything else relevant to the type of content you want to create.</p><p>If you want a swipe file with 77 post templates, here’s <a href="https://app.kortex.co/public/document/47b0dbfc-45df-43ae-802e-45b7eadd87e9" target="_blank" rel="noreferrer">my idea museum.</a></p><p><strong>2) Study writing frameworks.</strong></p><p>When I first started writing, frameworks were a lifesaver.</p><p>I read the book Ca$hvertising and learned the basics of frameworks like AIDA (attention, interest, desire, action).</p><p>As I got deeper into copywriting, I learned about PAS for short-form promotions and PASTOR for long form sales letters.</p><p>It’s safe to say that by using these for my writing, not only could I write faster, but I felt confident that I was being attention grabbing and persuasive.</p><p>Along with your swipe file of content, <em>research 5-10 copywriting frameworks.</em></p><p>You can use ChatGPT (or Kortex AI next month) for this if you’d like.</p><p>Or, if you want another template to continue filling up your second brain with useful notes, here is an explanation of the <a href="https://app.kortex.co/public/document/bec7fcec-d76c-4d00-8669-37f53892fead" target="_blank" rel="noreferrer">Pain &amp; Process framework.</a></p><p><strong>3) Have them open as you write.</strong></p><p>I say “write,” but this applies to all types of content.</p><p>If you write the script for your reels, TikToks, or YouTube videos first, you gain physical control over your articulation. You can <em>see</em> the hook, the sentences, the ideas, and move them around like legos until they’re beautiful. Don’t go into content as a beginner blindly.</p><ul><li>Capture ideas throughout the week</li><li>Sit down 2-3 days out of the week for 1-2 hours</li><li>Open up Kortex or another writing/notes software</li><li>Paste in your content frameworks</li><li>Open them in a pane on the side</li><li>Write out your ideas and reference the frameworks</li></ul><p>You’re not copying the other people’s ideas. <em>You’re emulating the structure that makes them do well.</em></p><h3 id="_4-nobody-knows-who-you-are" tabindex="-1">4) Nobody Knows Who You Are <a class="header-anchor" href="#_4-nobody-knows-who-you-are" aria-label="Permalink to &quot;4) Nobody Knows Who You Are&quot;">​</a></h3><p>You have good content.</p><p>You know your ideas hit hard.</p><p>You’re writing all day every day, but you still gain maybe a few followers a day, max.</p><p>What’s the problem?</p><p><em>Nobody knows who you are.</em></p><p>You’re just waiting for your lord and savior the algorithm to launch your posts to the moon when that’s not going to happen. And even if it would, you should act like it wouldn’t. Your growth is on <em>you.</em> It’s in <em>your control…</em> if you know what you’re doing.</p><p>You see, content is one <em>small</em> part of the social media equation. Especially as a beginner.</p><p>The bigger part of the equation is:</p><ul><li>The amount of people who know and like you (because they’re more likely to share and engage with your posts)</li><li>The amount of people who see your posts (because almost nobody will as a beginner)</li><li>The quality of friendships you make with those on the rise (because they’ll pull you up as they grow)</li></ul><p>If you have 500 followers and get reposted by someone with 500,000 followers, your audience is now 500,500 followers.</p><p>This is how people make tens of thousands of dollars with a small audience. <em>They know how to network. They know how to get their content seen</em> <em><strong>beyond</strong></em> <em>their audience.</em></p><p>Beginners think they are limited to their follower count and the algorithm is how they grow.</p><p>Experts know they can access their own followers and their network’s followers. They write a post they know will bring in followers or sales and have 10-15 people share it. This isn’t something they do every day. It is strategic. They build up good will and act right when the time is right.</p><p>Sahil Bloom is someone to watch who is doing this right now. He has his book, <a href="https://www.amazon.com/gp/product/059372318X?tag=randohouseinc7986-20" target="_blank" rel="noreferrer">The 5 Types Of Wealth</a>, available for preorder (it’s going to be a best seller, easily, by the way, not because he has a large audience, but because he is smart). He is working day and night to get his books in as many hands as he can. He is sending free copies to at least 50 people on X, bookmarking pages for them to post that will go viral, and commenting on them with the link to the post. He has 1 million followers, but if I had to guess, these posts have been seen by 100 million people.</p><p>I’m rambling.</p><p>What can you do?</p><p><strong>1) Inject yourself in a tribe.</strong></p><p>The most basic social media advice is to “reply to large accounts a bunch.”</p><p>This works, and is important, but most people don’t know why they are doing it beyond getting a few impressions on their replies hoping that some will follow them.</p><p>In reality, you’re doing a few things:</p><ul><li>Writing <em>quality</em> replies (not “Great post!” or repeating what they said with ChatGPT) so people have a reason to look at your profile and follow you. Again, 10 Koemmandments.</li><li>Becoming well known to a tribe of people. If I wanted to break into a social media circle, like the startup circle, I would simply reply to 10 great accounts in that space by adding value and personal experience. The <em>consumers</em> in that space get used to your face and follow you after they see you enough, not after your first reply.</li><li>Seeding connections. The more you reply and DM people within a certain niche group, the easier it is to DM them, or have them DM you. They will engage more with your posts and feed you opportunities.</li></ul><p>Reply strategically.</p><p><strong>2) Practice non-needy networking.</strong></p><p>It’s a shame this has to be taught, but it does.</p><p>People no longer learn social skills in their everyday environment.</p><p>People are as afraid of DMing other people as they are saying hi to a random person on the street.</p><p>In reality, it’s as simple as <em>finding a shared interest.</em></p><p><img src="'+s+'" alt=""></p><p><img src="'+l+'" alt=""></p><p>It’s literally that simple.</p><p>Guess what I did on that thread he shared? I reposted it. Because I had a new friend and he was smart enough to send it.</p><p>Here’s another <a href="https://app.kortex.co/public/document/e5b5d206-0874-4637-9201-6cc0d6b2f583" target="_blank" rel="noreferrer">Kortex doc</a> with 7 non-needy networking steps if you want to add it to your workspace.</p><p>Send a compliment or question about their content. Talk for a bit. Then do this:</p><p><strong>3) Plan one strategic post a week.</strong></p><p>If you are only posting content, you will not grow.</p><p>Plain and simple.</p><p>And if you do grow, the algorithm will eventually change, and you will be floating off in the ocean without a support network.</p><p>You need to be having conversations every week. You need to be writing posts that add value to those conversations and sharing them with those people.</p><h3 id="_5-you-need-a-product" tabindex="-1">5) You Need A Product <a class="header-anchor" href="#_5-you-need-a-product" aria-label="Permalink to &quot;5) You Need A Product&quot;">​</a></h3><p>Most creators wait to monetize until they hit some imaginary follower count just to be disappointed when nobody buys.</p><p>Or, they think that they’ll make a decent income from platform monetization (like YouTube) until they hit a wall and their views plummet for 2 months.</p><p>The point is, if you want to be in control of your income, you need to sell a product or service.</p><p>This does a few things:</p><p><strong>1) People start to see you as an authority.</strong></p><p>Most creators build an audience of people that don’t care about them.</p><p>They don’t realize that content isn’t enough to build a deep connection with someone. People need to <em>invest in you</em> in order to pay more attention to you.</p><p>People aren’t on social media to learn and adopt new habits. They buy products for that. And once you change their habits, or change their life, they will hold you much higher in their mind.</p><p>Many creators plateau simply because they have a surface level audience.</p><p><strong>2) It gives you a frame and incentive for your content.</strong></p><p>If you don’t know what to write, write about a topic that solves a pain point related to the product or service you sell. Simple.</p><p>On top of that, many people don’t have a <em>reason</em> to continue creating content because there is no immediate reward.</p><p>If you have a product or service, you at least have the <em>potential</em> to make some money from it. You’re able to focus your efforts on the things that get results.</p><p><strong>3) It makes trial and error more tolerable.</strong></p><p>If something isn’t working, you <em>know</em> it isn’t working.</p><p>You aren’t getting clicks. You aren’t getting sales.</p><p>If you aren’t getting clicks, write content based around more pain points and get it spread to more people with non-needy networking.</p><p>If you aren’t getting sales, study offer creation and copywriting to convert more people.</p><p>If you don’t know where to start with a product or service, I show you how to build an “MVO” in the <a href="https://stan.store/thedankoe/p/the-oneperson-business-launchpad--your-first-5k" target="_blank" rel="noreferrer">One-Person Business Launchpad.</a></p><h3 id="_6-build-a-world-not-a-funnel" tabindex="-1">6) Build A World, Not A Funnel <a class="header-anchor" href="#_6-build-a-world-not-a-funnel" aria-label="Permalink to &quot;6) Build A World, Not A Funnel&quot;">​</a></h3><p>Gone are the days of countdown timers and fake scarcity.</p><p>Today, creators are building worlds, not funnels, although a simple newsletter and landing page can be considered a funnel. In that case, you’re building a world of mini funnels.</p><p>The average consumer doesn’t trust people out of the gate. You need both time in the game and enough value for them to explore in order for them to gain trust.</p><p>You need to build a small scale Marvel cinematic universe. You need to build movies, action figures, and lore that people can binge.</p><p>In other words, you need:</p><ul><li>Short form content (X, LinkedIn, Instagram, Threads, or TikTok)</li><li>Long form content (newsletter, podcast, or YouTube)</li><li>Free guides (ebooks, templates, video trainings)</li><li>Low ticket product (course, template, cohort)</li><li>High ticket product (coaching, freelancing, consulting)</li></ul><p>Start with one short form and one long form. I recommend X, LinkedIn, or Threads combined with a newsletter. Then, you can use those newsletters as YouTube scripts and cross post your short posts to all other platforms and use the best as reel or TikTok scripts.</p><p>Then, once you build enough distribution and cash flow, you have the resources to pivot into something like eCommerce or software.</p><p>Social posts are the new MVP.</p><p>Post a bunch. Turn the best into newsletters. Cross post those everywhere. Turn the best of the best into a digital product. Refine it until sales are high. Turn that system into a software, or compliment it with a physical product.</p><h3 id="_7-make-noise-double-down-on-signal" tabindex="-1">7) Make Noise, Double Down On Signal <a class="header-anchor" href="#_7-make-noise-double-down-on-signal" aria-label="Permalink to &quot;7) Make Noise, Double Down On Signal&quot;">​</a></h3><p>The last objection:</p><p>“But Dan, I want to write about my ideas in an authentic way. This whole social media thing feels so soulless and templated.”</p><p>I agree.</p><p>But to handle the first part, templates and frameworks don’t make you inauthentic. Creativity thrives with constraints, and a framework allows you to express your authentic ideas in a way that other people care about.</p><p>If you want to be purely “authentic” without regard for what others think, that’s great, but good luck being able to sustain that as a lifestyle that pays you. Not that money is the end all be all, but it is important, and it’s only as evil as the person who wields it.</p><p>For the second part, you <em>can</em> write about whatever you want.</p><p>You don’t have to fall into the trap of only writing content that performs in the algorithm.</p><p>You <em>should</em> make room for both. Content that you know will expose you to more people, and content that you think those people will love.</p><p>But if people don’t find you first, they don’t have a chance at seeing your other, deeper, ideas.</p><p>So, feel free to make a lot of noise.</p><p>Write about any idea your heart desires.</p><p>Pay attention to the ideas that people resonate with.</p><p>The ones that get slightly more engagement, DMs, or followers.</p><p>Then, incorporate them as a consistent part of your content strategy.</p><p>You don’t need to choose a niche. You need to experiment with ideas until people tell you what niche best suits your relationship with your audience.</p><p>If you want to learn more about my “you are the niche” philosophy, here’s a previous letter.</p><p>Thank you for reading.</p><p>– Dan</p>',285)])])}const T=p(c,[["render",m]]);export{I as __pageData,T as default};
